import{_ as o,o as t,c as i,ag as c}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-28（地球科学 / 环境 / 稻田甲基汞）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/science-daily-2026-10-28-earth.md","filePath":"topics/earth-science/science-daily-2026-10-28-earth.md"}'),n={name:"topics/earth-science/science-daily-2026-10-28-earth.md"};function r(s,e,a,d,l,g){return t(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="科学日报-·-2026-10-28-地球科学-环境-稻田甲基汞" tabindex="-1">科学日报 · 2026-10-28（地球科学 / 环境 / 稻田甲基汞） <a class="header-anchor" href="#科学日报-·-2026-10-28-地球科学-环境-稻田甲基汞" aria-label="Permalink to &quot;科学日报 · 2026-10-28（地球科学 / 环境 / 稻田甲基汞）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> — 第47期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-earth</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-28-稻田里的抗生素正在「催化」神经毒物——氟喹诺酮让甲基汞升高近-20" tabindex="-1">科学日报 2026-10-28：稻田里的抗生素正在「催化」神经毒物——氟喹诺酮让甲基汞升高近 20% <a class="header-anchor" href="#科学日报-2026-10-28-稻田里的抗生素正在「催化」神经毒物——氟喹诺酮让甲基汞升高近-20" aria-label="Permalink to &quot;科学日报 2026-10-28：稻田里的抗生素正在「催化」神经毒物——氟喹诺酮让甲基汞升高近 20%&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ DOI: 10.1038/s41467-026-79083-7 ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：抗生素残留已广泛存在于农业土壤，但它对<strong>微生物驱动的汞（Hg）转化</strong>及风险的影响一直不清楚。</li><li>方法：取中国主要稻区的 <strong>40 份稻田土</strong>，加入 <strong>10 mg/kg 氟喹诺酮（FQ）</strong> 培养 21 天；结合<strong>代谢抑制实验、微宇宙实验、富集 SRB 菌群宏基因组分析</strong>。</li><li>结果： <ul><li>FQ 使<strong>甲基汞（MeHg，神经毒性）含量升高 2.9%–19.7%</strong>；</li><li>升高主要来自<strong>被刺激的微生物汞甲基化</strong>，而非去甲基化受抑；</li><li>**硫酸盐还原菌（SRB）**主导——抑制硫酸盐还原使 FQ 诱导的 Hg 甲基化下降 <strong>31%–75%</strong>；</li><li>关键甲基化者是<strong>携带 hgcA 的 SRB</strong>：FQ <strong>选择性压制竞争菌群</strong>、扶持<strong>耐受抗生素且代谢活跃</strong>的 SRB（尤其走<strong>还原性乙酰辅酶 A 途径</strong>者），从而<strong>在不显著改变甲基化菌丰度或群落结构的前提下抬高甲基化活性</strong>。</li></ul></li><li>洞察（对本库 <code>earth-science</code> × <code>biomedicine</code>）： <ol><li><strong>「丰度不变但活性升高」＝效果藏在代谢状态，不在群落结构</strong> —— 热点不在「谁在场」而在「谁在干活」。判据：<strong>当某过程强度变了但组成没变时，去测「代谢活性/通路使用」而不是「丰度/结构」。</strong> 这与 10-27 生物医学「细胞状态而非细胞类型」是同一判据的跨域版本（状态/活性 &gt; 类型/丰度）。</li><li><strong>「抗生素的代价不止耐药性」——一个隐性耦合</strong>：FQ 本为杀菌而用，却<strong>顺带放大了汞的神经毒性暴露</strong>。判据：<strong>给土壤加一种强选择压力（抗生素）时，预期之外的目标（Hg 甲基化）可能被一并改变——即干预的副作用要走一遍元素循环，而非只看靶标。</strong></li><li><strong>对本库 <code>earth-science</code> 的价值</strong>：这是「人类活动 → 微生物群落 → 元素循环 → 毒物暴露」的完整链条案例，可与 10-27 巴伦支海（人类强迫 → 生产力）、10-25 劳伦泰德冰盖（人为升温终止冰期）并列，补强「人为强迫沿着意想不到的通道改变化学/生态」的库级主题。</li><li><strong>注意措辞克制</strong>：这是<strong>实验室培养 21 天的剂量—响应</strong>（40 份土、10 mg/kg），结论是「抗生素污染<strong>可能放大</strong>汞暴露风险」，<strong>不是</strong>已确立的田间风险；落库保留「提示/可能」而非「已证实」。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/earth-science/index.md</code> ｜ <code>topics/biomedicine/index.md</code> ｜ 第47期 科学板块</p></blockquote><p>关键词：科学日报第47期、稻田土、抗生素污染、氟喹诺酮 FQ、甲基汞 MeHg、神经毒物、微生物汞甲基化、硫酸盐还原菌 SRB、hgcA、还原性乙酰辅酶A途径、宏基因组、拥挤/竞争菌群压制、丰度不变活性升高、代谢状态而非群落结构、抗生素代价不止耐药性、隐性元素循环耦合、10 mg/kg 21天</p><p>关联：<code>topics/earth-science/index.md</code>、<code>topics/biomedicine/index.md</code>、<code>topics/earth-science/science-daily-2026-10-27-earth.md</code>（巴伦支海）、<code>topics/biomedicine/science-daily-2026-10-27-biomed.md</code>（细胞状态&gt;类型）、<code>topics/ai-brain/index.md</code></p>',10)])])}const h=o(n,[["render",r]]);export{m as __pageData,h as default};
